(function(){var box=document.getElementById("lv-vidbox"),pl=document.getElementById("lv-vidbox-player"),x=document.getElementById("lv-vidbox-close"),active=null;function open(u,poster){if(!u)return;active=document.activeElement;box.style.display="flex";box.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";pl.poster=poster||"";pl.setAttribute("src",u);pl.setAttribute("playsinline","");pl.setAttribute("webkit-playsinline","");pl.muted=false;pl.load();var play=pl.play();if(play&&play.catch)play.catch(function(){pl.controls=true})}function close(){pl.pause();pl.removeAttribute("src");pl.removeAttribute("poster");pl.load();box.style.display="none";box.setAttribute("aria-hidden","true");document.body.style.overflow="";if(active&&active.focus)active.focus();active=null}document.querySelectorAll(".lv-vid").forEach(function(b){b.addEventListener("click",function(){var img=b.querySelector("img");open(b.getAttribute("data-vid"),img?img.src:"")})});x.addEventListener("click",function(e){e.stopPropagation();close()});box.addEventListener("click",function(e){if(e.target===box)close()});pl.addEventListener("ended",close);document.addEventListener("keydown",function(e){if(e.key==="Escape"&&box.style.display==="flex")close()})})();